import fs from 'node:fs';
import path from 'node:path';
import crypto from 'node:crypto';
import {resolveContained} from './storage.mjs';

// Read only manifests generated by our sampler, never arbitrary image paths.
export function copySourceSurvey(root,workspaceId,manifestPath,selected,sources,destination,{expectedManifest}={}){
 if(!/^[a-zA-Z0-9-]+$/.test(workspaceId))throw new Error('Workspace không hợp lệ.');
 const located=resolveContained(root,manifestPath),folder=path.dirname(located.file);
 if(expectedManifest){if(located.file!==resolveContained(root,expectedManifest).file)throw new Error('Sai bảng ảnh dự án.');}
 else{
  const cache=resolveContained(root,path.join('workspace/contentos/source-previews',workspaceId)).file;
  if(path.dirname(folder)!==cache||!/^[-a-f0-9]{36}$/.test(path.basename(folder)))throw new Error('Sai kho ảnh khảo sát.');
 }
 const manifest=JSON.parse(fs.readFileSync(located.file,'utf8'));
 if(path.basename(located.file)!=='preview.json'||manifest.workspaceId!==workspaceId||manifest.media?.path!==selected)throw new Error('Bảng ảnh không khớp workspace/video chính.');
 if(!sources.some(s=>s.status==='ready'&&s.files?.some(f=>f.path===selected)))throw new Error('Nguồn bảng ảnh không còn trong yêu cầu dựng.');
 const declared=sources.find(s=>s.status==='ready'&&s.files?.some(f=>f.path===selected));
 const source=declared.kind==='file'?resolveContained(path.dirname(declared.path),path.basename(declared.path)):resolveContained(declared.path,path.relative(declared.path,selected));
 const stat=fs.statSync(source.file);
 if(stat.size!==manifest.media.bytes||stat.mtimeMs!==manifest.media.mtimeMs)throw new Error('Nguồn đã đổi. Tạo lại ảnh khảo sát trước khi giao AI.');
 if(!Array.isArray(manifest.frames)||manifest.frames.length!==6)throw new Error('Bảng ảnh cần đủ 6 khung hình.');
 const frames=manifest.frames.map((frame,i)=>{
  const file=resolveContained(root,frame.path).file;
  if(file!==path.join(folder,`frame-${i+1}.jpg`)||!Number.isFinite(frame.time)||frame.time<=0||frame.time>=manifest.media.duration)throw new Error('Khung hình khảo sát không hợp lệ.');
  const bytes=fs.readFileSync(file);
  if(bytes.length>2*1024**2||bytes[0]!==255||bytes[1]!==216||crypto.createHash('sha256').update(bytes).digest('hex')!==frame.sha256)throw new Error('Ảnh khảo sát đã đổi hoặc hỏng.');
  return {frame,bytes};
 });
 fs.mkdirSync(destination,{recursive:true});
 try{
  const copied={...manifest,frames:frames.map(({frame,bytes},i)=>{
   const file=path.join(destination,`frame-${i+1}.jpg`);fs.writeFileSync(file,bytes,{flag:'wx'});
   return {...frame,path:path.relative(root,file).replaceAll('\\','/')};
  })};
  const target=path.join(destination,'preview.json');fs.writeFileSync(target,JSON.stringify(copied,null,2)+'\n',{flag:'wx'});
  return {...copied,manifestPath:path.relative(root,target).replaceAll('\\','/')};
 }catch(error){fs.rmSync(destination,{recursive:true,force:true});throw error;}
}
